import * as TypeScript from 'typescript';
import * as WasmCompiler from 'esbuild-wasm';
import asset from 'esbuild-wasm/esbuild.wasm?url';
let loading;
export async function transform(input){
  const targets=new Map([['es2015',TypeScript.ScriptTarget.ES2015],['es2020',TypeScript.ScriptTarget.ES2020]]);
  if(!targets.has(input.target))throw Error('Unsupported target');
  switch(input.compiler||'typescript'){
    case'typescript':{
      const result=TypeScript.transpileModule(input.source,{compilerOptions:{target:targets.get(input.target)},reportDiagnostics:true});
      const diagnostics=Array.from(result.diagnostics||[],item=>{const at=item.file?.getLineAndCharacterOfPosition(item.start||0);return{message:TypeScript.flattenDiagnosticMessageText(item.messageText,'\n'),line:at?at.line+1:null,column:at?at.character+1:null};});
      return{code:diagnostics.length?'':result.outputText,diagnostics};
    }
    case'esbuild':{
      if(!loading)loading=WasmCompiler.initialize({wasmURL:asset}).catch(error=>{loading=null;throw error;});await loading;
      try{const result=await WasmCompiler.transform(input.source,{target:input.target,loader:'ts'});return{code:result.code,diagnostics:[]};}
      catch(error){if(!error.errors)throw error;return{code:'',diagnostics:error.errors.map(item=>({message:item.text,line:item.location?.line||null,column:item.location?item.location.column+1:null}))};}
    }
    default:throw Error('Unsupported compiler');
  }
}
